import{_ as t,o as a,c as n,a3 as r}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Purchases, fees and payouts","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/payments-payouts.md","filePath":"user/admin/payments-payouts.md"}'),s={name:"user/admin/payments-payouts.md"};function o(i,e,d,h,c,l){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="purchases-fees-and-payouts" tabindex="-1">Purchases, fees and payouts <a class="header-anchor" href="#purchases-fees-and-payouts" aria-label="Permalink to &quot;Purchases, fees and payouts&quot;">​</a></h1><h2 id="purchases" tabindex="-1">Purchases <a class="header-anchor" href="#purchases" aria-label="Permalink to &quot;Purchases&quot;">​</a></h2><p><strong>Purchases</strong> lists everything clients bought, across all centers. Open one to see its items, payments, discounts and <strong>financials</strong> (fee, platform subsidy and what the center earns). You can sort it by <strong>Total</strong> or <strong>Date</strong> and export the list. Each purchase shows its 6-character <strong>code</strong>, the one the client and the center see.</p><table tabindex="0"><thead><tr><th>Purchase status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>Created, not paid or confirmed yet</td></tr><tr><td><strong>Confirmed</strong></td><td>Paid in full (or cash on arrival accepted)</td></tr><tr><td><strong>Completed</strong></td><td>Fulfilled</td></tr><tr><td><strong>Cancelled</strong></td><td>Stopped; refunds follow the rules below</td></tr></tbody></table><p>A purchase becomes confirmed only when its successful payments add up to the full total. A failed payment can be retried; each try is a new payment record.</p><h2 id="platform-fees" tabindex="-1">Platform fees <a class="header-anchor" href="#platform-fees" aria-label="Permalink to &quot;Platform fees&quot;">​</a></h2><p>The <strong>platform fee</strong> is what a center owes the platform on a sale. It does <strong>not</strong> change what the client pays. Manage fee rules under <strong>Fees</strong> (you need the fee permission).</p><p>A rule can be percentage, fixed amount, or both, with a minimum and maximum. The first matching rule wins, in this order: the center&#39;s rule for the channel, the platform rule for the channel, the center&#39;s fallback, the platform fallback. Each channel (client app, center app, web, center dashboard) can have its own rule.</p><p>The fee is recorded once per sale and <strong>reversed</strong> if the purchase is cancelled or fully refunded. A partial refund keeps the fee.</p><h2 id="center-ledger-and-payouts" tabindex="-1">Center ledger and payouts <a class="header-anchor" href="#center-ledger-and-payouts" aria-label="Permalink to &quot;Center ledger and payouts&quot;">​</a></h2><p>Every online payment adds to the center&#39;s <strong>ledger</strong>. After a hold period it becomes available. Fees, refunds and discounts funded by the platform adjust the balance. <strong>Cash and manual payments stay with the center</strong> and are not paid out.</p><p>Once a week (Sunday, 00:00 UTC) the platform creates one <strong>pending payout</strong> per center for its available balance. A center is skipped when its balance is zero or negative; its balance carries to the next run. A center with <strong>no bank account</strong> set still gets a payout, with empty bank details, so get the account from the center before transferring.</p><p>Under <strong>Payouts</strong> you can open a payout, <strong>mark it paid</strong> after transferring the money (the center is notified), or <strong>cancel</strong> it. You can sort payouts by <strong>Amount</strong>, <strong>Entries</strong> or <strong>Period end</strong>, and a center&#39;s ledger by <strong>Amount</strong> or <strong>Payable from</strong>. You can export a center&#39;s ledger from the center page.</p><h2 id="payout-invoices" tabindex="-1">Payout invoices <a class="header-anchor" href="#payout-invoices" aria-label="Permalink to &quot;Payout invoices&quot;">​</a></h2><p>On a payout&#39;s page, <strong>Print invoice</strong> opens a PDF of the payout in <strong>Arabic</strong> or <strong>English</strong>. It shows the invoice number (<code>PO-</code> and the payout number), the dates, the status, the center, its bank details as they were when the payout was created, totals per entry type, every ledger entry, and the total to transfer in SAR. You can print a payout in any status; a cancelled payout is marked <strong>CANCELLED</strong> across the page.</p><p><strong>Payouts → Invoice template</strong> controls how every invoice looks: the logo (JPEG or PNG), the company name and address in both languages, the VAT and CR numbers, contact email and phone, the accent color, a note above and below the figures, and whether to show the bank details, the summary, the entry list and the signature lines. The preview beside the form updates as you edit, in either language, using sample figures. Nothing changes until you save, and the figures always come from the payout itself. You need the payouts permission.</p>',16)])])}const g=t(s,[["render",o]]);export{u as __pageData,g as default};
